 let datasets={},editions=[],jcrIndex=new Map(),last=null,comparison=null,busy=false,ready=false,page='results',tab='individual',pageNo=1,pageSize=50,filter={hq:'',dept:'',person:'',paper:'',review:false},applyExceptions=true,storeError='',modal=null,hiddenCols=new Set();
 let portalTask=null,rosterTask=null,rosterPreview=null,migrationNotice='';
 let host,shadow,app,dialogRoot;const $=s=>shadow.querySelector(s);const current=()=>state.years[state.year];
 const audit=(kind,before,after,note,by='담당자')=>{state.log.push({일시:new Date().toISOString(),평가연도:state.year,구분:kind,이전값:JSON.stringify(before),변경값:JSON.stringify(after),사유:note,처리자:by});};
 function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){storeError='설정 저장 실패: '+e.message;throw Error(storeError);}}
 function changed(kind,before,after,note,by){current().revision++;comparison=null;audit(kind,before,after,note,by);save();}
 function openDb(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB,1);r.onupgradeneeded=()=>r.result.createObjectStore('data');r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('다른 탭이 저장소를 사용 중입니다.'));r.onsuccess=()=>resolve(r.result);});}
 async function dbGet(key){const db=await openDb();try{return await new Promise((resolve,reject)=>{const r=db.transaction('data').objectStore('data').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}finally{db.close();}}
 async function dbPut(key,value){const db=await openDb();try{await new Promise((resolve,reject)=>{const t=db.transaction('data','readwrite');t.objectStore('data').put(value,key);t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error||Error('저장 취소'));});}finally{db.close();}}
 async function decodeBuiltins(){if(!root.KRISS_JCR_BUILTIN_GZIP)return [];const bytes=Uint8Array.from(atob(root.KRISS_JCR_BUILTIN_GZIP),c=>c.charCodeAt(0));return JSON.parse(await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text());}
 async function restore(){try{const results=await Promise.allSettled([dbGet('datasets'),dbGet('editions'),decodeBuiltins()]);if(results[0].status==='fulfilled')datasets=results[0].value||{};else storeError='브라우저 자료 저장소를 사용할 수 없습니다. 현재 세션에서만 자료가 유지됩니다.';const built=results[2].status==='fulfilled'?results[2].value:[];const saved=results[1].status==='fulfilled'?results[1].value||[]:[];editions=built.filter(b=>!saved.some(s=>s.submitYear===b.submitYear)).concat(saved);jcrIndex=E.indexJcr(editions);if(!editions.length)storeError+=' JCR 목록을 직접 업로드하세요.';}catch(e){storeError=e.message;}ready=true;render();}
