 function table(headers,records,{actions='',limit=true,sortKey='',presorted=false}={}){const visible=headers.filter(h=>!hiddenCols.has(h)),offset=limit?(pageNo-1)*pageSize:0,ordered=sortKey&&!presorted?sortedRows(records,sortKey):records,rr=limit?ordered.slice(offset,offset+pageSize):ordered;return `<div class="table-scroll"><table><thead><tr>${visible.map(h=>sortKey?sortHeader(h,sortKey):`<th>${esc(h)}</th>`).join('')}${actions?'<th>관리</th>':''}</tr></thead><tbody>${rr.length?rr.map((r,i)=>`<tr>${visible.map(h=>`<td class="${typeof r[h]==='number'?'num':''}" title="${esc(r[h])}">${typeof r[h]==='number'?esc(/연도/.test(h)?String(r[h]):/JCI|백분율/.test(h)?fmt(r[h],3):/점수|점 환산|참고 환산/.test(h)?fmt(r[h]):Number.isInteger(r[h])?r[h].toLocaleString('ko-KR'):fmt(r[h])):esc(r[h]??'—')}</td>`).join('')}${actions?`<td>${actions==='person'?button('보기','person-detail','link',`data-key="${esc(r.사번)}"`):actions==='dept'?button('보기','dept-detail','link',`data-hq="${esc(r['본부·소'])}"`):actions==='exception'?button('수정','edit-exception','link',`data-id="${esc(r.ID)}"`)+button('삭제','delete-exception','link danger',`data-id="${esc(r.ID)}"`):''}</td>`:''}</tr>`).join(''):`<tr><td colspan="${visible.length+(actions?1:0)}" class="empty">표시할 자료가 없습니다.</td></tr>`}</tbody></table></div>`;}
 function pager(count){const max=Math.max(1,Math.ceil(count/pageSize));return `<div class="pager">${button('처음','first-page')}${button('이전','prev-page')}<span>${pageNo} / ${max}</span>${button('다음','next-page','',`data-max="${max}"`)}${button('마지막','last-page','',`data-max="${max}"`)}<select id="page-size" aria-label="페이지당 행 수">${[50,100,200].map(n=>`<option ${n===pageSize?'selected':''}>${n}</option>`).join('')}</select><span>${count?((pageNo-1)*pageSize+1).toLocaleString():0}–${Math.min(pageNo*pageSize,count).toLocaleString()} / ${count.toLocaleString()}건</span></div>`;}
 const personRows=r=>r.persons.map(p=>({'본부·소':p.hq,부서명:p.dept,사번:p.sabun,성명:p.name,직종:p.job,상태:p.status,인정논문수:p.paperCount,'제1저자 건/점수':`${p.firstCount} / ${fmt(p.firstSum)}`,'교신저자 건/점수':`${p.corrCount} / ${fmt(p.corrSum)}`,'공저자 건/점수':`${p.coCount} / ${fmt(p.coSum)}`,논문점수합계:p.sum,검토논문수:p.pending}));
 const deptRows=r=>r.departmentSummary.map(d=>({'본부·소':d.hq,목표:d.goal,인정실적:d.actual,증감:d.delta,'증감률(%)':d.deltaPct,상태:d.status,검토논문수:d.pendingCount,'100점 환산':d.score100,'최종점수(10점)':d.score10,'참고 환산(100점)':d.referenceScore100,'참고 환산(10점)':d.referenceScore10,전년도실적:d.prior??null,A:d.a??null,B:d.b??null,자동후보:d.rawCount,중복제거:d.duplicateRemoved,예외추가:d.manualAdded,예외제외:d.manualExcluded}));
 function filtered(rr){return rr.filter(r=>(!filter.hq||[r['본부·소'],r.개인소속본부,r.실적인정본부,r.부서후보본부].includes(filter.hq))&&(!filter.dept||E.norm(r.부서명).includes(E.norm(filter.dept)))&&(!filter.person||E.norm(`${r.사번||r.저자사번||''} ${r.성명||''}`).includes(E.norm(filter.person)))&&(!filter.paper||E.norm(`${r.등록번호||''} ${r.논문제목||''}`).includes(E.norm(filter.paper))));}
