 function yearSelect(){return `<label>평가연도<select id="eval-year">${Object.keys(state.years).sort((a,b)=>b-a).map(y=>`<option ${+y===state.year?'selected':''}>${y}</option>`).join('')}</select></label>${button('새 평가연도','new-year')}`;}
